mapper.select:
SELECT u.id, u.username, u.nickname, u.avatar, u.phone, u.email, u.gender, u.role, u.status, u.create_time AS createTime, u.update_time AS updateTime, cr.id AS craftsmanId, cr.real_name AS realName, cr.craft_type AS craftType, cr.audit_status AS auditStatus, cr.reject_reason AS rejectReason, cr.follower_count AS followerCount FROM `user` u LEFT JOIN craftsman cr ON cr.user_id = u.id AND cr.deleted = 0 WHERE u.deleted = 0
AND u.role = #{q.role}
AND u.status = #{q.status}
AND cr.audit_status = #{q.auditStatus}
AND (u.username LIKE CONCAT('%', #{q.keyword}, '%') OR u.nickname LIKE CONCAT('%', #{q.keyword}, '%') OR u.phone LIKE CONCAT('%', #{q.keyword}, '%') OR cr.real_name LIKE CONCAT('%', #{q.keyword}, '%'))
AND u.create_time >= #{q.startTime}
AND u.create_time <= #{q.endTime}
ORDER BY u.create_time DESC, u.id DESC
